51	void *riscv_dispatch_irq(uintptr_t vector, uintreg_t *regs)
52	{
53	  int irq = (vector & 0x3f);
54	  DEBUGASSERT(irq <= RISCV_IRQ_EXT);
55	
56	  if ((vector & RISCV_IRQ_BIT) != 0)
57	    {
58	       irq += RISCV_IRQ_ASYNC;
59	    }
60	
61	  if (irq < RISCV_IRQ_EXT)
62	    {
63	      regs = riscv_doirq(irq, regs);
64	    }
65	  else
66	    {
67	      uint32_t ext = getreg32(LITEX_PLIC_CLAIM);
68	      do
69	        {
70	          regs = riscv_doirq(RISCV_IRQ_EXT + ext, regs);
71	          putreg32(ext, LITEX_PLIC_CLAIM);
72	          ext = getreg32(LITEX_PLIC_CLAIM);
73	        }
74	      while (ext);
75	    }
76	
77	  return regs;
78	}
79	#else
