81	{
82	  int i;
83	  int irq = (vector >> RV_IRQ_MASK) | (vector & 0xf);
84	
85	  /* Firstly, check if the irq is machine external interrupt */
86	
87	  if (RISCV_IRQ_MEXT == irq)
88	    {
89	      /* litex vexriscv dont follow riscv plic standard */
90	
91	      unsigned int pending;
92	      unsigned int mask;
93	      asm volatile ("csrr %0, %1" : "=r"(pending) : "i"(LITEX_MPENDING_CSR));
94	      asm volatile ("csrr %0, %1" : "=r"(mask) : "i"(LITEX_MMASK_CSR));
95	
96	      uint32_t val = (pending & mask);
97	      for (i = 0; i < 32; i++)
98	        {
99	          if (val & (1 << i))
100	            {
101	              val = i;
102	              val++;
103	              break;
104	            }
105	        }
106	
107	      /* Add the value to nuttx irq which is offset to the mext */
108	
109	      irq += val;
110	    }
111	
112	  /* Acknowledge the interrupt */
113	
114	  riscv_ack_irq(irq);
115	
116	  /* Deliver the IRQ */
117	
118	  regs = riscv_doirq(irq, regs);
119	
120	  return regs;
